mkitem!{mkstruct!{# [doc = " A low-level synchronization primitive for one-time global execution."] # [doc = ""] # [doc = " Previously this was the only \"execute once\" synchronization in `std`."] # [doc = " Other libraries implemented novel synchronizing types with `Once`, like"] # [doc = " [`OnceLock<T>`] or [`LazyLock<T, F>`], before those were added to `std`."] # [doc = " `OnceLock<T>` in particular supersedes `Once` in functionality and should"] # [doc = " be preferred for the common case where the `Once` is associated with data."] # [doc = ""] # [doc = " This type can only be constructed with [`Once::new()`]."] # [doc = ""] # [doc = " # Examples"] # [doc = ""] # [doc = " ```"] # [doc = " use std::sync::Once;"] # [doc = ""] # [doc = " static START: Once = Once::new();"] # [doc = ""] # [doc = " START.call_once(|| {"] # [doc = "     // run initialization here"] # [doc = " });"] # [doc = " ```"] # [doc = ""] # [doc = " [`OnceLock<T>`]: crate::sync::OnceLock"] # [doc = " [`LazyLock<T, F>`]: crate::sync::LazyLock"] # [stable (feature = "rust1" , since = "1.0.0")] pub struct Once { inner : sys :: Once , }}}
