mkitem!{mkstruct!{# [doc = " State yielded to [`Once::call_once_force()`]’s closure parameter. The state"] # [doc = " can be used to query the poison status of the [`Once`]."] # [stable (feature = "once_poison" , since = "1.51.0")] pub struct OnceState { pub (crate) inner : sys :: OnceState , }}}
mkitem!{mkenum!{pub (crate) enum ExclusiveState { Incomplete , Poisoned , Complete , }}}
mkitem!{# [doc = " Initialization value for static [`Once`] values."] # [doc = ""] # [doc = " # Examples"] # [doc = ""] # [doc = " ```"] # [doc = " use std::sync::{Once, ONCE_INIT};"] # [doc = ""] # [doc = " static START: Once = ONCE_INIT;"] # [doc = " ```"] # [stable (feature = "rust1" , since = "1.0.0")] # [deprecated (since = "1.38.0" , note = "the `Once::new()` function is now preferred" , suggestion = "Once::new()")] pub const ONCE_INIT : Once = Once :: new () ;}
mkitem!{mkimpl!{impl Once { # [doc = " Creates a new `Once` value."] # [inline] # [stable (feature = "once_new" , since = "1.2.0")] # [rustc_const_stable (feature = "const_once_new" , since = "1.32.0")] # [must_use] pub const fn new () -> Once { Once { inner : sys :: Once :: new () } } # [doc = " Performs an initialization routine once and only once. The given closure"] # [doc = " will be executed if this is the first time `call_once` has been called,"] # [doc = " and otherwise the routine will *not* be invoked."] # [doc = ""] # [doc = " This method will block the calling thread if another initialization"] # [doc = " routine is currently running."] # [doc = ""] # [doc = " When this function returns, it is guaranteed that some initialization"] # [doc = " has run and completed (it might not be the closure specified). It is also"] # [doc = " guaranteed that any memory writes performed by the executed closure can"] # [doc = " be reliably observed by other threads at this point (there is a"] # [doc = " happens-before relation between the closure and code executing after the"] # [doc = " return)."] # [doc = ""] # [doc = " If the given closure recursively invokes `call_once` on the same [`Once`]"] # [doc = " instance, the exact behavior is not specified: allowed outcomes are"] # [doc = " a panic or a deadlock."] # [doc = ""] # [doc = " # Examples"] # [doc = ""] # [doc = " ```"] # [doc = " use std::sync::Once;"] # [doc = ""] # [doc = " static mut VAL: usize = 0;"] # [doc = " static INIT: Once = Once::new();"] # [doc = ""] # [doc = " // Accessing a `static mut` is unsafe much of the time, but if we do so"] # [doc = " // in a synchronized fashion (e.g., write once or read all) then we're"] # [doc = " // good to go!"] # [doc = " //"] # [doc = " // This function will only call `expensive_computation` once, and will"] # [doc = " // otherwise always return the value returned from the first invocation."] # [doc = " fn get_cached_val() -> usize {"] # [doc = "     unsafe {"] # [doc = "         INIT.call_once(|| {"] # [doc = "             VAL = expensive_computation();"] # [doc = "         });"] # [doc = "         VAL"] # [doc = "     }"] # [doc = " }"] # [doc = ""] # [doc = " fn expensive_computation() -> usize {"] # [doc = "     // ..."] # [doc = " # 2"] # [doc = " }"] # [doc = " ```"] # [doc = ""] # [doc = " # Panics"] # [doc = ""] # [doc = " The closure `f` will only be executed once even if this is called"] # [doc = " concurrently amongst many threads. If that closure panics, however, then"] # [doc = " it will *poison* this [`Once`] instance, causing all future invocations of"] # [doc = " `call_once` to also panic."] # [doc = ""] # [doc = " This is similar to [poisoning with mutexes][poison], but this mechanism"] # [doc = " is guaranteed to never skip panics within `f`."] # [doc = ""] # [doc = " [poison]: struct.Mutex.html#poisoning"] # [inline] # [stable (feature = "rust1" , since = "1.0.0")] # [track_caller] pub fn call_once < F > (& self , f : F) where F : FnOnce () , { if self . inner . is_completed () { return ; } let mut f = Some (f) ; self . inner . call (false , & mut | _ | f . take () . unwrap () ()) ; } # [doc = " Performs the same function as [`call_once()`] except ignores poisoning."] # [doc = ""] # [doc = " Unlike [`call_once()`], if this [`Once`] has been poisoned (i.e., a previous"] # [doc = " call to [`call_once()`] or [`call_once_force()`] caused a panic), calling"] # [doc = " [`call_once_force()`] will still invoke the closure `f` and will _not_"] # [doc = " result in an immediate panic. If `f` panics, the [`Once`] will remain"] # [doc = " in a poison state. If `f` does _not_ panic, the [`Once`] will no"] # [doc = " longer be in a poison state and all future calls to [`call_once()`] or"] # [doc = " [`call_once_force()`] will be no-ops."] # [doc = ""] # [doc = " The closure `f` is yielded a [`OnceState`] structure which can be used"] # [doc = " to query the poison status of the [`Once`]."] # [doc = ""] # [doc = " [`call_once()`]: Once::call_once"] # [doc = " [`call_once_force()`]: Once::call_once_force"] # [doc = ""] # [doc = " # Examples"] # [doc = ""] # [doc = " ```"] # [doc = " use std::sync::Once;"] # [doc = " use std::thread;"] # [doc = ""] # [doc = " static INIT: Once = Once::new();"] # [doc = ""] # [doc = " // poison the once"] # [doc = " let handle = thread::spawn(|| {"] # [doc = "     INIT.call_once(|| panic!());"] # [doc = " });"] # [doc = " assert!(handle.join().is_err());"] # [doc = ""] # [doc = " // poisoning propagates"] # [doc = " let handle = thread::spawn(|| {"] # [doc = "     INIT.call_once(|| {});"] # [doc = " });"] # [doc = " assert!(handle.join().is_err());"] # [doc = ""] # [doc = " // call_once_force will still run and reset the poisoned state"] # [doc = " INIT.call_once_force(|state| {"] # [doc = "     assert!(state.is_poisoned());"] # [doc = " });"] # [doc = ""] # [doc = " // once any success happens, we stop propagating the poison"] # [doc = " INIT.call_once(|| {});"] # [doc = " ```"] # [inline] # [stable (feature = "once_poison" , since = "1.51.0")] pub fn call_once_force < F > (& self , f : F) where F : FnOnce (& OnceState) , { if self . inner . is_completed () { return ; } let mut f = Some (f) ; self . inner . call (true , & mut | p | f . take () . unwrap () (p)) ; } # [doc = " Returns `true` if some [`call_once()`] call has completed"] # [doc = " successfully. Specifically, `is_completed` will return false in"] # [doc = " the following situations:"] # [doc = "   * [`call_once()`] was not called at all,"] # [doc = "   * [`call_once()`] was called, but has not yet completed,"] # [doc = "   * the [`Once`] instance is poisoned"] # [doc = ""] # [doc = " This function returning `false` does not mean that [`Once`] has not been"] # [doc = " executed. For example, it may have been executed in the time between"] # [doc = " when `is_completed` starts executing and when it returns, in which case"] # [doc = " the `false` return value would be stale (but still permissible)."] # [doc = ""] # [doc = " [`call_once()`]: Once::call_once"] # [doc = ""] # [doc = " # Examples"] # [doc = ""] # [doc = " ```"] # [doc = " use std::sync::Once;"] # [doc = ""] # [doc = " static INIT: Once = Once::new();"] # [doc = ""] # [doc = " assert_eq!(INIT.is_completed(), false);"] # [doc = " INIT.call_once(|| {"] # [doc = "     assert_eq!(INIT.is_completed(), false);"] # [doc = " });"] # [doc = " assert_eq!(INIT.is_completed(), true);"] # [doc = " ```"] # [doc = ""] # [doc = " ```"] # [doc = " use std::sync::Once;"] # [doc = " use std::thread;"] # [doc = ""] # [doc = " static INIT: Once = Once::new();"] # [doc = ""] # [doc = " assert_eq!(INIT.is_completed(), false);"] # [doc = " let handle = thread::spawn(|| {"] # [doc = "     INIT.call_once(|| panic!());"] # [doc = " });"] # [doc = " assert!(handle.join().is_err());"] # [doc = " assert_eq!(INIT.is_completed(), false);"] # [doc = " ```"] # [stable (feature = "once_is_completed" , since = "1.43.0")] # [inline] pub fn is_completed (& self) -> bool { self . inner . is_completed () } # [doc = " Blocks the current thread until initialization has completed."] # [doc = ""] # [doc = " # Example"] # [doc = ""] # [doc = " ```rust"] # [doc = " use std::sync::Once;"] # [doc = " use std::thread;"] # [doc = ""] # [doc = " static READY: Once = Once::new();"] # [doc = ""] # [doc = " let thread = thread::spawn(|| {"] # [doc = "     READY.wait();"] # [doc = "     println!(\"everything is ready\");"] # [doc = " });"] # [doc = ""] # [doc = " READY.call_once(|| println!(\"performing setup\"));"] # [doc = " ```"] # [doc = ""] # [doc = " # Panics"] # [doc = ""] # [doc = " If this [`Once`] has been poisoned because an initialization closure has"] # [doc = " panicked, this method will also panic. Use [`wait_force`](Self::wait_force)"] # [doc = " if this behavior is not desired."] # [stable (feature = "once_wait" , since = "1.86.0")] pub fn wait (& self) { if ! self . inner . is_completed () { self . inner . wait (false) ; } } # [doc = " Blocks the current thread until initialization has completed, ignoring"] # [doc = " poisoning."] # [doc = ""] # [doc = " If this [`Once`] has been poisoned, this function blocks until it"] # [doc = " becomes completed, unlike [`Once::wait()`], which panics in this case."] # [stable (feature = "once_wait" , since = "1.86.0")] pub fn wait_force (& self) { if ! self . inner . is_completed () { self . inner . wait (true) ; } } # [doc = " Returns the current state of the `Once` instance."] # [doc = ""] # [doc = " Since this takes a mutable reference, no initialization can currently"] # [doc = " be running, so the state must be either \"incomplete\", \"poisoned\" or"] # [doc = " \"complete\"."] # [inline] pub (crate) fn state (& mut self) -> ExclusiveState { self . inner . state () } # [doc = " Sets current state of the `Once` instance."] # [doc = ""] # [doc = " Since this takes a mutable reference, no initialization can currently"] # [doc = " be running, so the state must be either \"incomplete\", \"poisoned\" or"] # [doc = " \"complete\"."] # [inline] pub (crate) fn set_state (& mut self , new_state : ExclusiveState) { self . inner . set_state (new_state) ; } }}}
