mkitem!{mkimpl!{impl OnceState { # [doc = " Returns `true` if the associated [`Once`] was poisoned prior to the"] # [doc = " invocation of the closure passed to [`Once::call_once_force()`]."] # [doc = ""] # [doc = " # Examples"] # [doc = ""] # [doc = " A poisoned [`Once`]:"] # [doc = ""] # [doc = " ```"] # [doc = " use std::sync::Once;"] # [doc = " use std::thread;"] # [doc = ""] # [doc = " static INIT: Once = Once::new();"] # [doc = ""] # [doc = " // poison the once"] # [doc = " let handle = thread::spawn(|| {"] # [doc = "     INIT.call_once(|| panic!());"] # [doc = " });"] # [doc = " assert!(handle.join().is_err());"] # [doc = ""] # [doc = " INIT.call_once_force(|state| {"] # [doc = "     assert!(state.is_poisoned());"] # [doc = " });"] # [doc = " ```"] # [doc = ""] # [doc = " An unpoisoned [`Once`]:"] # [doc = ""] # [doc = " ```"] # [doc = " use std::sync::Once;"] # [doc = ""] # [doc = " static INIT: Once = Once::new();"] # [doc = ""] # [doc = " INIT.call_once_force(|state| {"] # [doc = "     assert!(!state.is_poisoned());"] # [doc = " });"] # [stable (feature = "once_poison" , since = "1.51.0")] # [inline] pub fn is_poisoned (& self) -> bool { self . inner . is_poisoned () } # [doc = " Poison the associated [`Once`] without explicitly panicking."] # [inline] pub (crate) fn poison (& self) { self . inner . poison () ; } }}}
mkitem!{mkimpl!{# [stable (feature = "std_debug" , since = "1.16.0")] impl fmt :: Debug for OnceState { fn fmt (& self , f : & mut fmt :: Formatter < '_ >) -> fmt :: Result { f . debug_struct ("OnceState") . field ("poisoned" , & self . is_poisoned ()) . finish () } }}}